import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { useState } from "react";

export default function CheckboxControlledExample() {
  const [checked, setChecked] = useState(false);

  return (
    <div className="flex flex-col gap-group">
      <Field orientation="horizontal">
        <Checkbox checked={checked} onCheckedChange={setChecked} />
        <FieldLabel>Receive marketing emails</FieldLabel>
      </Field>
      <p className="text-caption text-muted-foreground">
        checked: <code>{String(checked)}</code>
      </p>
    </div>
  );
}

import ExampleCheckboxControlled from "../examples/checkbox-controlled";

const Example = () => <ExampleCheckboxControlled />;

export default Example;
